from pathlib import Path
from html import escape
from urllib.parse import quote
import re, shutil, json, sys
from PIL import Image
from bs4 import BeautifulSoup
from data import FAMILIES, ALLOYS, FLASKS
ROOT=Path(__file__).resolve().parents[1]; SITE=ROOT/'site'; REF=ROOT/'reference'
(SITE/'assets/img').mkdir(parents=True,exist_ok=True)
for p in (SITE/'assets/img').glob('*'): p.unlink()
logo = Image.open(ROOT/'img-originals/logo/original.jpg').convert('RGB')
logo.resize((492,188), Image.Resampling.LANCZOS).save(SITE/'assets/img/crosbie-logo.png')
def image_for(name):
 
 if name in ('example1','example3'): return name+'.jpg'
 s=BeautifulSoup((REF/f'html/{name}.html.html').read_text(errors='ignore'),'html.parser'); im=s.find('img'); return im.get('src') if im else None
images={}
for slug,(title,desc,names) in FAMILIES.items():
 for name in names:
  source=image_for(name); path=REF/'img'/source
  if not path.exists(): print('missing',path); continue
  im=Image.open(path); im.thumbnail(im.size); dest=f'{name}.jpg'; im.convert('RGB').save(SITE/'assets/img'/dest,quality=82,optimize=True)
  images[name]=(dest,*im.size)
def img(name,alt):
 f,w,h=images[name]; return f'<img src="/assets/img/{f}" width="{w}" height="{h}" alt="{escape(alt)}" loading="lazy" style="max-width:min(100%, {int(w*1.25)}px)">'
nav=[('Products','/products/'),('Services','/services/'),('Alloys','/alloys/'),('About','/about/'),('History','/history/'),('Contact','/contact/')]
def shell(title,description,body,path):
 subnav='<ul class="mobile-products">' + ' '.join(f'<li><a href="/products/{slug}/"'+(' aria-current="page"' if path==f'/products/{slug}/' else '')+f'>{escape(family_title)}</a></li>' for slug,(family_title,_,_) in FAMILIES.items()) + '</ul>'
 links='<ul class="nav-list">' + ' '.join(f'<li><a href="{url}"'+(' aria-current="page"' if path==url or (url=='/products/' and path.startswith(url)) else '')+f'>{label}</a>'+(subnav if url=='/products/' else '')+'</li>' for label,url in nav) + '</ul>'
 footer_links=' '.join(f'<a href="{url}">{label}</a>' for label,url in nav)
 org={'@context':'https://schema.org','@type':'Organization','name':'Crosbie Foundry','url':'https://www.crosbiefoundry.com/','telephone':'800-419-0402','faxNumber':'574-262-1503','email':'crosbiefoundry@aol.com','address':{'@type':'PostalAddress','streetAddress':'1600 Mishawaka St.','addressLocality':'Elkhart','addressRegion':'IN','postalCode':'46514'}}
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="robots" content="noindex"><title>{escape(title)} | Crosbie Foundry</title><meta name="description" content="{escape(description,quote=True)}"><meta property="og:title" content="{escape(title)} | Crosbie Foundry"><meta property="og:description" content="{escape(description,quote=True)}"><meta property="og:type" content="website"><meta property="og:url" content="https://www.crosbiefoundry.com{path}"><link rel="icon" href="/favicon.svg" type="image/svg+xml"><link rel="preload" href="/assets/fonts/zilla-slab-latin-700-normal.woff2" as="font" type="font/woff2" crossorigin><link rel="stylesheet" href="/assets/css/site.css"><script type="application/ld+json">{json.dumps(org)}</script><script src="/assets/js/site.js" defer></script></head><body><a class="skip" href="#main">Skip to content</a><header class="header"><div class="wrap header-inner"><a class="header-phone" href="tel:8004190402">800-419-0402</a> <a class="brand" href="/"><img src="/assets/img/crosbie-logo.png" width="246" height="94" alt="Crosbie Foundry"></a> <button class="menu-button" type="button" aria-expanded="false" aria-controls="navigation">Menu</button><nav id="navigation" aria-label="Main navigation">{links}</nav></div></header><main id="main">{body}</main><footer><div class="wrap footer-grid"><div><a class="footer-brand" href="/"><img src="/assets/img/crosbie-logo.png" width="246" height="94" alt="Crosbie Foundry"></a><p>1600 Mishawaka St.<br>Elkhart, IN 46514</p></div><div><a href="tel:8004190402">800-419-0402</a><br><a href="tel:5742621502">574-262-1502</a><br>Fax 574-262-1503<br><a href="mailto:crosbiefoundry@aol.com">crosbiefoundry@aol.com</a></div><div class="footer-nav">{footer_links}</div></div></footer></body></html>'''
def write(path,title,desc,body):
 p=SITE/('index.html' if path=='/' else path.strip('/')+'/index.html'); p.parent.mkdir(parents=True,exist_ok=True); p.write_text(shell(title,desc,body,path))
def intro(title,text=''): return f'<section class="page-intro"><div class="wrap"><h1>{title}</h1>{f"<p>{text}</p>" if text else ""}</div></section>'
def cards():
 return '<div class="family-grid">'+' '.join(f'<a class="family-card" href="/products/{slug}/"><div class="card-image">{img(names[0],title)}</div><div class="card-title"><h3>{title}</h3></div></a>' for slug,(title,desc,names) in FAMILIES.items())+'</div>'
quote_band='<section class="quote-band"><div class="wrap quote-inner"><a href="tel:8004190402">800-419-0402</a> <a class="button light" href="/contact/#quote-form">Request a quote</a></div></section>'
product_quote='<a class="button dark product-quote" href="/contact/#quote-form">Request a quote</a>'
flasks='<div class="table-wrap" tabindex="0"><table class="flasks"><caption>Typical production flask sizes</caption><tbody>'+''.join('<tr>'+''.join(f'<td>{escape(x)}</td>' for x in FLASKS[i:i+2])+'</tr>' for i in range(0,len(FLASKS),2))+'</tbody></table></div>'
home='''<section class="hero"><div class="wrap hero-inner"><div><span class="hero-stamp">Est. 1956</span><h1>Brass, bronze and aluminum sand castings</h1><div class="actions"><a class="button light" href="/contact/#quote-form">Request a quote </a> <a class="text-link" href="/products/">Explore products </a></div></div><img class="hero-photo" src="/assets/img/valve1.jpg" width="604" height="304" alt="Bronze valve castings" fetchpriority="high"></div></section><section class="section"><div class="wrap"><div class="section-heading"><h2>Products</h2><a class="inline-link" href="/products/">All products </a></div>'''+cards()+'''</div></section><section class="section"><div class="wrap split"><div><h2>About the foundry</h2><p class="lead">Crosbie Foundry has specialized in sand castings since 1956.</p><p>Working exclusively with nonferrous metals, Crosbie Foundry uses green sand to produce fine-finish castings with consistent tolerances.</p><p>Short-run and prototype parts are handled alongside large production orders. Parts typically range from a couple of ounces to about five pounds, though larger parts are also produced.</p><a class="inline-link" href="/services/">Our services </a></div><div class="capabilities"><h3>Capabilities</h3><ul><li>Pattern making & prototyping</li><li>Machining & coring</li><li>Polishing & plating</li><li>Test bars & certifications</li></ul></div></div></section><section class="section muted"><div class="wrap flask-section"><h2>Flask sizes</h2><div>'''+flasks+'''<a class="inline-link" href="/alloys/">View alloys </a></div></div></section>'''+quote_band
write('/','Brass, bronze and aluminum sand castings','Crosbie Foundry produces nonferrous green-sand castings in Elkhart, Indiana.',home)
# Preserve the complete applications list directly from the source.
source = BeautifulSoup((REF/'html/products.html.html').read_text(errors='ignore'), 'html.parser')
paragraph = next(p.get_text(' ', strip=True) for p in source.find_all('p') if 'castings for all of the following applications:' in p.get_text(' ', strip=True))
applications = [re.sub(r'\s+', ' ', item).strip().rstrip('.') for item in paragraph.split('applications:', 1)[1].split(',')]
groups = {group: [] for group in ('Aluminum', 'Brass', 'Bronze', 'Other')}
for item in sorted(applications, key=str.casefold):
 group = item.split()[0].capitalize()
 groups[group if group in groups else 'Other'].append(item)
application_html = ''.join(f'<section class="application-group"><div class="application-start"><h3>{group}</h3><ul><li>{escape(items[0])}</li></ul></div><ul>' + ''.join(f'<li>{escape(item)}</li>' for item in items[1:]) + '</ul></section>' for group, items in groups.items() if items)
products=intro('Products')+'<section class="section"><div class="wrap">'+cards()+product_quote+'</div></section><section class="section muted"><div class="wrap"><h2>Applications</h2><div class="applications">'+application_html+'</div></div></section>'
write('/products/','Products','Brass, bronze, and aluminum castings for a wide range of applications.',products)
for slug,(title,desc,names) in FAMILIES.items():
 siblings='<nav class="siblings" aria-label="Product families"><a href="/products/">All products</a><ul>' + ' '.join(f'<li><a href="/products/{other}/"'+(' aria-current="page"' if other==slug else '')+f'>{escape(other_title)}</a></li>' for other,(other_title,_,_) in FAMILIES.items()) + '</ul></nav>'
 gallery=' '.join(f'<a class="gallery-item" href="/assets/img/{images[n][0]}">{img(n,title)}</a>' for n in names if n in images)
 write('/products/'+slug+'/',title,desc,intro(title)+'<section class="product-section"><div class="wrap product-layout">'+siblings+'<div class="product-content"><p>'+escape(desc)+'</p>'+product_quote+'<div class="gallery">'+gallery+'</div></div></div></section>')
write('/services/','Services','Pattern making, prototyping, machining, coring, polishing, plating, and tooling services.',intro('Services')+'''<section class="section"><div class="wrap split"><div><h2>From pattern to casting</h2><p>Our services include pattern making, prototyping, machining, coring, polishing, and plating. We provide test bars and certifications for any production alloy.</p><p>Tooling services are available for your product. Grinding and polishing are readily available, and design consultation is available upon request.</p></div><div class="capabilities"><h3>Production</h3><p>Short-run and prototype parts are readily handled alongside large production orders.</p><p>Local pick-up and delivery are available. Please call for more information.</p></div></div></section>'''+quote_band)
rows=''.join('<tr>'+''.join(('<th scope="row">'+escape(c)+'</th>' if i==0 else '<td>'+escape(c)+'</td>') for i,c in enumerate(row))+'</tr>' for row in ALLOYS)
write('/alloys/','Alloys','Alloys regularly used by Crosbie Foundry.',intro('Alloys','These are alloys we use on a regular basis; we can run any alloy in these bronze families.')+'<section class="section"><div class="wrap"><p class="scroll-cue">Scroll table horizontally →</p><div class="table-wrap alloy-table" tabindex="0" role="region" aria-label="Alloys table, scroll horizontally"><table><thead><tr><th scope="col">Copper Alloy</th><th scope="col">Ingot Number</th><th scope="col">Metal Name</th><th scope="col">Nominal Composition</th></tr></thead><tbody>'+rows+'</tbody></table></div></div></section>'+quote_band)
write('/about/','About','Crosbie Foundry is family owned and operated since 1956.',intro('About the foundry')+'''<section class="section"><div class="wrap split"><div><h2>Since 1956</h2><p>Crosbie Foundry was founded in 1956. Design consultation is available upon request. Contact us for a quote or with tooling and design questions.</p><a class="inline-link" href="/history/">Our history</a></div><div><h2>Our team</h2><ul class="team"><li><strong>John Crosbie</strong><span>Owner / Operations Manager</span></li><li><strong>Greg Crosbie</strong><span>Owner / General Manager</span></li><li><strong>Dan Crosbie</strong><span>Owner / Maintenance</span></li><li><strong>Joe Crosbie</strong><span>Shift Manager / Sales</span></li><li><strong>Linda Crosbie</strong><span>Office Manager / Accounting</span></li></ul></div></div></section>'''+quote_band)
write('/history/','History','Crosbie Foundry has been family owned and operated since 1956.',intro('Our history')+'''<section class="section"><div class="wrap prose"><p class="lead">Crosbie Foundry started out supplying polished musical instrument keys to local band instrument manufacturers.</p><p>The foundry specializes in castings for firefighting equipment, key blanks, clamps, valves, plaques, signage, and decorative hardware.</p><h2>Signage and castings</h2><p>Crosbie Foundry has provided signage for U.S. Open golf courses Pebble Beach, Oakmont, Olympia Fields, Medinah, Winged Foot, and Torre Pines. For the PGA Championship, the foundry has supplied signage to Crooked Stick, Valhalla, Medinah, Winged Foot, and Atlanta Athletic Club.</p><p>Crosbie Foundry has also provided signage to Augusta National Golf Club and to Turnberry Golf Club for the 2009 British Open. A key to the City of Elkhart presented to President Obama was produced at Crosbie Foundry.</p></div></section>'''+quote_band)
fields=[('Name','name','text','name',True),('Company','company','text','organization',False),('Email','email','email','email',True),('Phone','phone','tel','tel',False),('Part description','part','text','off',True),('Alloy','alloy','text','off',False),('Quantity','quantity','text','off',False)]
form=''.join(f'<label>{label}<input name="{label}" type="{typ}" autocomplete="{auto}"'+(' required' if req else '')+'></label>' for label,name,typ,auto,req in fields)+'<label class="full">Message<textarea name="Message" rows="5"></textarea></label>'
write('/contact/','Contact','Contact Crosbie Foundry in Elkhart, Indiana for a casting quote.',intro('Contact')+'''<section class="section"><div class="wrap contact-grid"><div><h2>Crosbie Foundry</h2><p>1600 Mishawaka St.<br>Elkhart, IN 46514</p><div class="contact-details"><p>Toll free<br><a href="tel:8004190402">800-419-0402</a></p><p>Local<br><a href="tel:5742621502">574-262-1502</a></p><p>Fax<br>574-262-1503</p><p>Email<br><a href="mailto:crosbiefoundry@aol.com">crosbiefoundry@aol.com</a></p></div></div><div class="quote-form-section"><h2>Request a quote</h2><form id="quote-form">'''+form+'''<div class="full"><button class="button dark" type="submit">Prepare email</button><p id="form-status" role="status"></p></div></form></div></div></section>''')
# redirects
mapping={'contact':'/contact/','products':'/products/','service':'/services/','alloys':'/alloys/','about':'/about/','history':'/history/','links':'/','Home':'/','decorative':'/products/decorative-tiles/','golfcourse':'/products/golf-plaques/','corners':'/products/corner-castings/','brass':'/products/decorative-hardware/','clamps':'/products/clamps/','registerhardware':'/products/cash-register-hardware/','miscellaneous':'/products/miscellaneous/','valve':'/products/valves/'}
for slug,(_,_,names) in FAMILIES.items():
 for n in names:
  if n not in ('example1','example3'): mapping[n]='/products/'+slug+'/'
(SITE/'_redirects').write_text(''.join(f'/{k}.html {v} 301\n' for k,v in mapping.items()))
(SITE/'_headers').write_text('/*\n  X-Content-Type-Options: nosniff\n  Referrer-Policy: strict-origin-when-cross-origin\n  X-Frame-Options: DENY\n  X-Robots-Tag: noindex\n\n/assets/*\n  Cache-Control: public, max-age=31536000, immutable\n')
(SITE/'robots.txt').write_text('User-agent: *\nDisallow: /\nSitemap: https://www.crosbiefoundry.com/sitemap.xml\n')
paths=['/','/products/','/services/','/alloys/','/about/','/history/','/contact/']+['/products/'+s+'/' for s in FAMILIES]
(SITE/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join('<url><loc>https://www.crosbiefoundry.com'+p+'</loc></url>' for p in paths)+'</urlset>')
(SITE/'404.html').write_text(shell('Page not found','Page not found.',intro('Page not found','The page you requested could not be found.')+'<section class="section"><div class="wrap"><a class="button dark" href="/">Return home</a></div></section>','/404.html'))
(SITE/'favicon.svg').write_text('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64"><rect width="64" height="64" fill="#202f82"/><text x="32" y="42" text-anchor="middle" font-family="sans-serif" font-weight="bold" font-size="27" fill="#fff">CF</text></svg>')
print('Built',len(paths),'pages plus 404')
